#include "stdafx.h"#include "HcdElementBase.h"#include <HcdMemoryService.h>#include <HcdDataTypes_.h>struct S8DI_P{#include "PrivateVars/8DI.h"};class K8DI : public KHcdElementBase  , protected S8DI_P{  W_8DI *m_pHardware;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _8DI("8DI", K8DI::Create);IHcdElement *K8DI::Create(){  return new K8DI;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( K8DI, 25 )void K8DI::InitParm(){#include "PrivateVars/8DI.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void K8DI::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  m_pHardware = (W_8DI*)KMemoryServiceHCD::Instance().IoCreateObj( szName, W_8DI::TypeID, domain );  m_pSharedObject = (BYTE*)m_pHardware;  m_pSharedVarsInfo = new SVarInfo[8];  AddSharedField( "RAW1", NULL, offsetof(W_8DI, W_8DI::RAW1), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW2", NULL, offsetof(W_8DI, W_8DI::RAW2), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW3", NULL, offsetof(W_8DI, W_8DI::RAW3), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW4", NULL, offsetof(W_8DI, W_8DI::RAW4), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW5", NULL, offsetof(W_8DI, W_8DI::RAW5), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW6", NULL, offsetof(W_8DI, W_8DI::RAW6), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW7", NULL, offsetof(W_8DI, W_8DI::RAW7), ehtBool, sizeof(tBool), 8 );  AddSharedField( "RAW8", NULL, offsetof(W_8DI, W_8DI::RAW8), ehtBool, sizeof(tBool), 8 );  qsort( m_pSharedVarsInfo, m_kSharedVarsInfo, sizeof( SVarInfo ), CompVarInfo );}void K8DI::StepCalc( SStepCalcParams &params ){  tBool *pOUTRx = &OUTR0;  tBool *pInvertx = &IC1;  tBool *pRawx = &m_pHardware->RAW1;  for( int i=0; i<8; ++i )  {    if( pInvertx[i] )      pOUTRx[i] = pRawx[i] ? 0 : 1;    else      pOUTRx[i] = pRawx[i];  }}